 public static void Android(){
  Validate();Plugins(BuildTarget.Android);var questConfig=OVRProjectConfig.CachedProjectConfig;questConfig.handTrackingSupport=OVRProjectConfig.HandTrackingSupport.ControllersAndHands;OVRProjectConfig.CommitProjectConfig(questConfig);var pipeline=AssetDatabase.LoadAssetAtPath<RenderPipelineAsset>("Assets/Settings/Mobile_RPAsset.asset");GraphicsSettings.defaultRenderPipeline=pipeline;QualitySettings.renderPipeline=pipeline;var s=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene);var guids=AssetDatabase.FindAssets("OVRCameraRig t:Prefab");var rig=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(AssetDatabase.GUIDToAssetPath(guids[0])));var manager=rig.GetComponent<OVRManager>();if(!manager)manager=rig.AddComponent<OVRManager>();manager.isInsightPassthroughEnabled=true;var layer=rig.AddComponent<OVRPassthroughLayer>();layer.overlayType=OVROverlay.OverlayType.Underlay;foreach(var c in rig.GetComponentsInChildren<Camera>()){c.clearFlags=CameraClearFlags.SolidColor;c.backgroundColor=Color.clear;c.nearClipPlane=.01f;}new GameObject("Colored dots / ArUco").AddComponent<QuestMarkerTracker>();
  string scene="Assets/MarkerLab/QuestMarkerScene.unity";EditorSceneManager.SaveScene(s,scene);EditorBuildSettings.scenes=new[]{new EditorBuildSettingsScene(scene,true)};PlayerSettings.productName="Interactive Paper Lab";PlayerSettings.SetApplicationIdentifier(UnityEditor.Build.NamedBuildTarget.Android,"org.openclaw.markertrackinglab");PlayerSettings.Android.bundleVersionCode=13;PlayerSettings.bundleVersion="0.13-teaching-capture";PlayerSettings.SetScriptingBackend(UnityEditor.Build.NamedBuildTarget.Android,ScriptingImplementation.IL2CPP);PlayerSettings.Android.targetArchitectures=AndroidArchitecture.ARM64;PlayerSettings.Android.useCustomKeystore=false;PlayerSettings.allowUnsafeCode=true;AssetDatabase.SaveAssets();Finish(scene,Environment.GetEnvironmentVariable("MARKER_APK")??"Builds/marker-tracking-lab.apk",BuildTarget.Android);
